# /// script
# requires-python = ">=3.9"
# ///
"""
Run after `--write-verification-metadata` (#246, #238). Key servers answer on some runs and not others:
a key that couldn't be downloaded once is listed under <ignored-keys>, and when a later run does download
it and trusts groups with it, Gradle keeps the old "ignored" entry. An ignored key wins, so the artifacts
it signs end up with neither a usable key nor a checksum, and verification fails on them. This drops every
ignored key that is also trusted (its key is then in verification-keyring.keys).

The same race can pin one artifact to a key (<pgp value>) that is also ignored, while the rest of the
component, signed by the same key, got checksums (#273). Unignoring the key would leave those untrusted, so
the pinned artifact gets a checksum too, from the file Gradle just verified in its cache. Nothing else changes.
"""
import hashlib
import os
import re
import sys
from pathlib import Path

path = Path(sys.argv[1] if len(sys.argv) > 1 else "gradle/verification-metadata.xml")
text = path.read_text()
trusted = {fp[-16:] for fp in re.findall(r'<trusted-key id="([0-9A-F]+)"', text)}
stale = [k for k in re.findall(r'<ignored-key id="([0-9A-F]+)"', text) if k in trusted]
for key in stale:
    text = re.sub(r'\n\s*<ignored-key id="%s"[^>]*/>' % key, "", text)

ignored = set(re.findall(r'<ignored-key id="([0-9A-F]+)"', text))
cache = Path(os.environ.get("GRADLE_USER_HOME", Path.home() / ".gradle")) / "caches/modules-2/files-2.1"
pinned = []


def checksum(component):
    group, name, version = component.group(1), component.group(2), component.group(3)

    def artifact(a):
        if not any(k[-16:] in ignored for k in re.findall(r'<pgp value="([0-9A-F]+)"', a.group(0))):
            return a.group(0)
        files = list((cache / group / name / version).glob("*/" + a.group(1)))
        if len(files) != 1:
            sys.exit("Not in Gradle's cache (run the --write-verification-metadata build first): %s:%s:%s %s" % (group, name, version, a.group(1)))
        digest = hashlib.sha256(files[0].read_bytes()).hexdigest()
        pinned.append(a.group(1))
        return '<artifact name="%s">\n            <sha256 value="%s" origin="Generated by Gradle" reason="A key couldn\'t be downloaded"/>\n         </artifact>' % (a.group(1), digest)

    return re.sub(r'<artifact name="([^"]+)">.*?</artifact>', artifact, component.group(0), flags=re.S)


text = re.sub(r'<component group="([^"]+)" name="([^"]+)" version="([^"]+)">.*?</component>', checksum, text, flags=re.S)
path.write_text(text)
print("Dropped ignored keys that are trusted:", ", ".join(stale) if stale else "none")
print("Checksums for artifacts pinned to an ignored key:", ", ".join(pinned) if pinned else "none")
